import React, { useState, useEffect } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { onAuthStateChanged } from 'firebase/auth';
import { auth } from './firebase/config';
import './index.css';
import Header from './components/Header';
import Hero from './components/Hero';
import FeaturedProjects from './components/FeaturedProjects';
import BeforeAfter from './components/BeforeAfter';
import Calculator from './components/Calculator';
import AboutUs from './components/AboutUs';
import Services from './components/Services';
import Testimonials from './components/Testimonials';
import Footer from './components/Footer';
import Reference from './components/Reference';
import LineButton from './components/LineButton';
import BlogTeaser from './components/BlogTeaser';
import WorkProcess from './components/WorkProcess';
import Admin from './pages/Admin';
import AdminLogin from './pages/AdminLogin';
import Blog from './pages/Blog';
import Article from './pages/Article';
import { getSettings } from './firebase/api';

const MainSite = () => {
  const [show, setShow] = useState({});

  useEffect(() => {
    getSettings()
      .then(data => {
        const obj = {};
        data.forEach(s => { obj[s.setting_key] = s.setting_value; });
        setShow(obj);
      })
      .catch(err => console.error('Error fetching section settings:', err));
  }, []);

  // Scroll to a #hash target after mount (e.g. arriving from /blog via "/#contact")
  useEffect(() => {
    if (window.location.hash) {
      const id = window.location.hash.slice(1);
      const t = setTimeout(() => {
        document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' });
      }, 600);
      return () => clearTimeout(t);
    }
  }, []);

  // default visible: only hide when the flag is explicitly false
  const on = (key) => show[key] !== false;

  return (
    <>
      <Header />
      <main>
        {on('show_hero') && <Hero />}
        {on('show_beforeafter') && <BeforeAfter />}
        {on('show_projects') && <FeaturedProjects />}
        {on('show_reference') && <Reference />}
        {on('show_calculator') && <Calculator />}
        {on('show_process') && <WorkProcess />}
        {on('show_about') && <AboutUs />}
        {on('show_services') && <Services />}
        {on('show_reviews') && <Testimonials />}
        {on('show_blog') && <BlogTeaser />}
        <Footer />
      </main>
      <LineButton />
    </>
  );
};

const ProtectedRoute = ({ isAuthenticated, element }) => {
  return isAuthenticated ? element : <Navigate to="/admin/login" replace />;
};

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setIsAuthenticated(!!user);
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  if (loading) {
    return <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh' }}>Loading...</div>;
  }

  return (
    <Routes>
      <Route path="/" element={<MainSite />} />
      <Route path="/blog" element={<Blog />} />
      <Route path="/blog/:slug" element={<Article />} />
      <Route path="/admin/login" element={<AdminLogin setIsAuthenticated={setIsAuthenticated} />} />
      <Route
        path="/admin"
        element={<ProtectedRoute isAuthenticated={isAuthenticated} element={<Admin setIsAuthenticated={setIsAuthenticated} />} />}
      />
    </Routes>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { getContentByKey, getSettings } from '../firebase/api';
import { useCountUp } from '../lib/motion';
import './AboutUs.css';

const AboutUs = () => {
  const [aboutContent, setAboutContent] = useState({
    description: 'ด้วยประสบการณ์ในงานก่อสร้างและงานต่อเติมมากกว่า 30 ปี เราให้บริการงานต่อเติมบ้าน รีโนเวท ปรับปรุงอาคาร และงานก่อสร้างทั่วไป โดยดูแลทุกขั้นตอนตั้งแต่สำรวจหน้างาน ประเมินราคา วางแผนงาน ไปจนถึงการส่งมอบงาน\n\nเราให้ความสำคัญกับคุณภาพ ความปลอดภัย และความรับผิดชอบในทุกโครงการ พร้อมรับประกันผลงาน 1 ปี เพื่อสร้างความมั่นใจให้กับลูกค้าหลังส่งมอบงาน'
  });
  const [stats, setStats] = useState({
    projects: '500',
    team: '30',
    satisfaction: '95'
  });
  const [showStats, setShowStats] = useState(true);
  const projectsRef = useCountUp(stats.projects, { suffix: '+' });
  const teamRef = useCountUp(stats.team, { suffix: '+' });
  const satisfactionRef = useCountUp(stats.satisfaction, { suffix: '%' });

  useEffect(() => {
    const fetchContent = async () => {
      try {
        const [descData, settingsData] = await Promise.all([
          getContentByKey('about_description'),
          getSettings()
        ]);

        if (descData.thai_content) {
          setAboutContent({ description: descData.thai_content });
        }

        const settingsObj = {};
        settingsData.forEach(s => {
          settingsObj[s.setting_key] = s.setting_value;
        });

        setStats({
          projects: settingsObj.projects_count || '500',
          team: settingsObj.team_count || '30',
          satisfaction: settingsObj.satisfaction_percent || '95'
        });

        setShowStats(settingsObj.show_about_stats !== false);
      } catch (err) {
        console.error('Error fetching about content:', err);
      }
    };
    fetchContent();
  }, []);

  return (
    <section className="about section" id="about">
      <div className="container">
        <div className="about-head">
          <h2 className="section-title text-left">ABOUT US</h2>
          <p className="about-text">{aboutContent.description}</p>
        </div>

        {/* Bento grid — craftsmanship-focused, no people photos needed */}
        <div className="about-bento">
          {/* Large: work-detail photo (no faces) */}
          <div className="bento-cell bento-photo">
            <img
              src="/website/uploads/1779821114162-539615797.png"
              alt="ดีเทลงานตกแต่งห้องน้ำหินอ่อนโดย BSBuildTh"
              loading="lazy"
              decoding="async"
            />
            <span className="bento-photo-tag">งานจริงจากทีมช่างของเรา</span>
          </div>

          {/* Stats */}
          {showStats && (
            <div className="bento-cell bento-stats">
              <div className="stat-item">
                <h3 className="stat-number" ref={projectsRef}>{stats.projects}+</h3>
                <p className="stat-label">Projects</p>
              </div>
              <div className="stat-item">
                <h3 className="stat-number" ref={teamRef}>{stats.team}+</h3>
                <p className="stat-label">Structural Experts</p>
              </div>
              <div className="stat-item">
                <h3 className="stat-number" ref={satisfactionRef}>{stats.satisfaction}%</h3>
                <p className="stat-label">Happy Clients</p>
              </div>
            </div>
          )}

          {/* Guarantee badge */}
          <div className="bento-cell bento-guarantee">
            <span className="bento-guarantee-icon" aria-hidden="true">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" width="34" height="34">
                <path d="M12 2l7 4v6c0 4.5-3 8.5-7 10-4-1.5-7-5.5-7-10V6l7-4z"/>
                <polyline points="9 12 11 14 15 10"/>
              </svg>
            </span>
            <h3>รับประกันผลงาน 1 ปี</h3>
            <p>มีปัญหาหลังส่งมอบ เรากลับมาดูแลให้</p>
          </div>

          {/* Why us */}
          <div className="bento-cell bento-why">
            <h3>ทำไมลูกค้าเลือกเรา</h3>
            <ul>
              <li><span>✓</span> คุมงานเองทุกโครงการ ไม่ทิ้งงาน</li>
              <li><span>✓</span> วัสดุมาตรฐาน ระบุในสัญญาชัดเจน</li>
              <li><span>✓</span> แบ่งงวดจ่ายตามความคืบหน้าจริง</li>
            </ul>
          </div>
        </div>
      </div>
    </section>
  );
};

export default AboutUs;

import React, { useState, useEffect, useRef } from 'react';
import { getImages } from '../firebase/api';
import './BeforeAfter.css';

const BeforeAfter = () => {
  const [sliderPos, setSliderPos] = useState(50);
  const containerRef = useRef(null);
  const [images, setImages] = useState({
    after: '/after_living_room.png',
    before: '/before_living_room.png'
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchBeforeAfterImages = async () => {
      try {
        const data = await getImages('before_after');

        // Organize images by key: before_after_after and before_after_before
        const imageMap = {};
        data.forEach(img => {
          imageMap[img.image_key] = img;
        });

        setImages({
          after: imageMap['before_after_after']?.image_path || '/after_living_room.png',
          before: imageMap['before_after_before']?.image_path || '/before_living_room.png'
        });
      } catch (err) {
        console.error('Error fetching before/after images:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchBeforeAfterImages();
  }, []);

  const handleSliderChange = (e) => {
    setSliderPos(e.target.value);
  };

  const setPosFromX = (clientX) => {
    const el = containerRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    const p = ((clientX - r.left) / r.width) * 100;
    setSliderPos(Math.max(2, Math.min(98, p)));
  };
  // Single press-and-drag: bind move/up on the document so dragging starts
  // immediately from the first pointer-down (no second click needed).
  const startDrag = (e) => {
    setPosFromX(e.clientX);
    const move = (ev) => setPosFromX(ev.clientX);
    const up = () => {
      document.removeEventListener('pointermove', move);
      document.removeEventListener('pointerup', up);
    };
    document.addEventListener('pointermove', move);
    document.addEventListener('pointerup', up);
  };

  if (loading) {
    return (
      <section className="before-after section" id="portfolio">
        <div className="container" data-aos="fade-up">
          <h2 className="section-title text-center">BEFORE & AFTER</h2>
          <p className="text-center text-muted mb-3">Slide to see the transformation.</p>
          <div className="slider-container" style={{ height: '400px', background: '#e0e0e0', borderRadius: '8px' }}></div>
        </div>
      </section>
    );
  }

  return (
    <section className="before-after section" id="portfolio">
      <div className="container" data-aos="fade-up">
        <h2 className="section-title text-center">BEFORE & AFTER</h2>
        <p className="text-center text-muted mb-3">Slide to see the transformation.</p>
        <div
          className="slider-container"
          ref={containerRef}
          onPointerDown={startDrag}
        >
          <div className="image-after">
            <img src={images.after} alt="After Renovation" loading="lazy" decoding="async" />
            <span className="ba-tag ba-tag--after">After</span>
          </div>
          <div className="image-before" style={{ clipPath: `polygon(0 0, ${sliderPos}% 0, ${sliderPos}% 100%, 0 100%)` }}>
            <img src={images.before} alt="Before Renovation" loading="lazy" decoding="async" />
            <span className="ba-tag ba-tag--before">Before</span>
          </div>
          <input
            type="range"
            min="0"
            max="100"
            value={sliderPos}
            onChange={handleSliderChange}
            className="slider-input"
            aria-label="เลื่อนเปรียบเทียบก่อน-หลัง"
          />
          <div className="slider-line" style={{ left: `${sliderPos}%` }}>
            <div className="slider-button">↔</div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default BeforeAfter;

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { getArticles } from '../firebase/api';
import './BlogTeaser.css';

const fmtDate = (d) => {
  try {
    return new Date(d).toLocaleDateString('th-TH', { year: 'numeric', month: 'short', day: 'numeric' });
  } catch { return ''; }
};

const BlogTeaser = () => {
  const [articles, setArticles] = useState([]);

  useEffect(() => {
    getArticles()
      .then(data => setArticles(data.slice(0, 3)))
      .catch(err => console.error('Failed to load articles:', err));
  }, []);

  if (articles.length === 0) return null;

  return (
    <section className="blogteaser section" id="articles">
      <div className="container">
        <div className="blogteaser-head" data-aos="fade-up">
          <div>
            <p className="eyebrow">ARTICLES & KNOWLEDGE</p>
            <h2 className="section-title">บทความ &amp; ความรู้</h2>
          </div>
          <Link to="/blog" className="blogteaser-all">อ่านบทความทั้งหมด →</Link>
        </div>

        <div className="blogteaser-grid">
          {articles.map(a => (
            <Link to={`/blog/${a.slug}`} className="blogteaser-card" key={a.id} data-aos="fade-up">
              <div className="blogteaser-img">
                {a.cover && <img src={a.cover} alt={a.title} loading="lazy" decoding="async" />}
              </div>
              <div className="blogteaser-body">
                {a.category && <span className="blogteaser-cat">{a.category}</span>}
                <h3 className="blogteaser-title">{a.title}</h3>
                <span className="blogteaser-date">{fmtDate(a.created_at)}</span>
              </div>
            </Link>
          ))}
        </div>
      </div>
    </section>
  );
};

export default BlogTeaser;

import React, { useState, useEffect, useMemo } from 'react';
import { getCalculatorTypes } from '../firebase/api';
import './Calculator.css';

const MIN_AREA = 10;
const MAX_AREA = 300;

const Calculator = () => {
  const [calculatorTypes, setCalculatorTypes] = useState([]);
  const [projectTypeId, setProjectTypeId] = useState(null);
  const [area, setArea] = useState(25);
  const [width, setWidth] = useState('5');
  const [length, setLength] = useState('5');
  const [loading, setLoading] = useState(true);

  // เมื่อกรอกกว้าง×ยาว → คำนวณพื้นที่ให้อัตโนมัติ
  const applyDimensions = (w, l) => {
    setWidth(w);
    setLength(l);
    const a = Math.round((parseFloat(w) || 0) * (parseFloat(l) || 0));
    if (a > 0) setArea(Math.min(Math.max(a, MIN_AREA), MAX_AREA));
  };

  useEffect(() => {
    const fetchTypes = async () => {
      try {
        const data = await getCalculatorTypes();
        setCalculatorTypes(data);
        if (data.length > 0) setProjectTypeId(data[0].id);
      } catch (err) {
        console.error('Error fetching calculator types:', err);
      } finally {
        setLoading(false);
      }
    };
    fetchTypes();
  }, []);

  // Live estimate — recomputes instantly when type or area changes (no button)
  const estimate = useMemo(() => {
    const selected = calculatorTypes.find(t => t.id === projectTypeId);
    if (!selected || !area) return null;
    const base = Number(selected.base_price) || 0;
    return {
      min: Math.floor(base * area * 0.9),
      max: Math.floor(base * area * 1.2),
    };
  }, [calculatorTypes, projectTypeId, area]);

  const fmt = (n) => n.toLocaleString('th-TH');
  const pct = ((area - MIN_AREA) / (MAX_AREA - MIN_AREA)) * 100;

  // ส่งสรุปการประเมินไปกรอกในฟอร์มขอใบเสนอราคาอัตโนมัติ (ผู้ใช้พิมพ์ต่อได้)
  const handleRequestQuote = () => {
    const selected = calculatorTypes.find(t => t.id === projectTypeId);
    const typeName = selected?.type_name || '';
    const dims = (width && length) ? `${width} × ${length} ม. ` : '';
    const lines = [
      `สนใจงาน: ${typeName}`,
      `พื้นที่: ${dims}(${area} ตร.ม.)`,
      estimate ? `งบประมาณโดยประมาณ: ${fmt(estimate.min)} – ${fmt(estimate.max)} บาท` : '',
      '',
      'รายละเอียดเพิ่มเติม: ',
    ].filter(Boolean);
    window.dispatchEvent(new CustomEvent('prefill-quote', {
      detail: { message: lines.join('\n'), serviceType: typeName },
    }));
  };

  if (loading) {
    return (
      <section className="calculator section" id="calculator">
        <div className="container">
          <div className="calc-wrapper">
            <div className="calc-info">
              <div className="skeleton skeleton-title"></div>
              <div className="skeleton skeleton-text" style={{ width: '80%' }}></div>
              <div className="skeleton skeleton-text" style={{ width: '60%' }}></div>
            </div>
            <div className="calculator-form">
              <div className="skeleton skeleton-input"></div>
              <div className="skeleton skeleton-input"></div>
              <div className="skeleton skeleton-btn"></div>
            </div>
          </div>
        </div>
      </section>
    );
  }

  return (
    <section className="calculator section" id="calculator">
      <div className="container" data-aos="fade-up">
        <div className="calc-wrapper">
          <div className="calc-info">
            <p className="eyebrow">ประเมินราคาฟรี</p>
            <h2 className="section-title text-left">ประเมินงบเบื้องต้น</h2>
            <p className="text-muted">เลือกประเภทงานและพื้นที่ เพื่อรับประเมินราคาและสำรวจหน้างานฟรี ในพื้นที่กรุงเทพมหานครและปริมณฑล</p>
            <ul className="text-muted">
              <li>✓ คำนวณสดแบบ Real-time</li>
              <li>✓ อ้างอิงฐานข้อมูลวัสดุปี 2026</li>
            </ul>
          </div>

          <div className="calc-interactive-container">
            <div className="calculator-form">
              {/* Type chips */}
              <div className="calc-form-group">
                <label>ประเภทงาน</label>
                <div className="calc-chips" role="radiogroup" aria-label="ประเภทงาน">
                  {calculatorTypes.map(type => (
                    <button
                      key={type.id}
                      type="button"
                      role="radio"
                      aria-checked={projectTypeId === type.id}
                      className={`calc-chip ${projectTypeId === type.id ? 'active' : ''}`}
                      onClick={() => setProjectTypeId(type.id)}
                    >
                      {type.type_name}
                    </button>
                  ))}
                </div>
              </div>

              {/* Width × Length → area */}
              <div className="calc-form-group">
                <label>กว้าง × ยาว (เมตร)</label>
                <div className="calc-dim-row">
                  <input
                    type="number"
                    inputMode="decimal"
                    min="0"
                    className="calc-dim-input"
                    placeholder="กว้าง"
                    value={width}
                    onChange={e => applyDimensions(e.target.value, length)}
                    aria-label="ความกว้าง (เมตร)"
                  />
                  <span className="calc-dim-x">×</span>
                  <input
                    type="number"
                    inputMode="decimal"
                    min="0"
                    className="calc-dim-input"
                    placeholder="ยาว"
                    value={length}
                    onChange={e => applyDimensions(width, e.target.value)}
                    aria-label="ความยาว (เมตร)"
                  />
                  <span className="calc-dim-eq">= {area} ตร.ม.</span>
                </div>
              </div>

              {/* Area slider */}
              <div className="calc-form-group">
                <label>
                  ปรับพื้นที่
                  <span className="calc-area-value">{area} <small>ตร.ม.</small></span>
                </label>
                <input
                  type="range"
                  className="calc-slider"
                  min={MIN_AREA}
                  max={MAX_AREA}
                  step="5"
                  value={area}
                  onChange={e => { setArea(Number(e.target.value)); setWidth(''); setLength(''); }}
                  style={{ '--pct': `${pct}%` }}
                  aria-label="ขนาดพื้นที่ (ตารางเมตร)"
                />
                <div className="calc-slider-scale">
                  <span>{MIN_AREA}</span>
                  <span>{MAX_AREA}+ ตร.ม.</span>
                </div>
              </div>
            </div>

            {estimate && (
              <div className="calculator-result" key={`${projectTypeId}-${area}`}>
                <h3>ช่วงงบประมาณโดยประมาณ (บาท)</h3>
                <div className="price-range">
                  <span className="price-min">{fmt(estimate.min)}</span>
                  <span className="price-sep">–</span>
                  <span className="price-max">{fmt(estimate.max)}</span>
                </div>
                <p className="disclaimer">*ราคาประเมินเบื้องต้น อาจเปลี่ยนแปลงตามหน้างานจริง</p>
                <a href="#contact" className="btn btn-solid calc-cta" onClick={handleRequestQuote}>ขอใบเสนอราคา →</a>
              </div>
            )}
          </div>
        </div>
      </div>
    </section>
  );
};

export default Calculator;

import React, { useState, useEffect, useRef } from 'react';
import { getProjects, getProject } from '../firebase/api';
import './FeaturedProjects.css';

const CATEGORY_LABELS = {
  interior: 'ตกแต่งภายใน',
  exterior: 'ต่อเติมภายนอก',
  renovation: 'รีโนเวท'
};

const FeaturedProjects = () => {
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [selectedProject, setSelectedProject] = useState(null);
  const [projectDetail, setProjectDetail] = useState(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [procIdx, setProcIdx] = useState(0);

  const scrollRef = useRef(null);
  const pausedRef = useRef(false);
  const dragRef = useRef({ active: false, startX: 0, startScroll: 0, moved: false });
  const resumeTimer = useRef(null);

  const apiUrl = import.meta.env.VITE_API_URL || '';

  useEffect(() => {
    getProjects()
      .then(data => { setProjects(data); setLoading(false); })
      .catch(err => { console.error('Failed to fetch projects:', err); setLoading(false); });
  }, []);

  useEffect(() => {
    document.body.style.overflow = selectedProject ? 'hidden' : '';
    return () => { document.body.style.overflow = ''; };
  }, [selectedProject]);

  const filteredProjects = (projects || []).filter(p => filter === 'all' || (p.category || 'renovation') === filter);

  // Auto-scroll loop (pauses on hover / user interaction). Cards are duplicated
  // once so scrollLeft can wrap seamlessly at the halfway point.
  useEffect(() => {
    const el = scrollRef.current;
    if (!el || filteredProjects.length === 0) return;
    let raf;
    const tick = () => {
      if (el && !pausedRef.current && !dragRef.current.active) {
        el.scrollLeft += 0.5;
        const half = el.scrollWidth / 2;
        if (half > 0 && el.scrollLeft >= half) el.scrollLeft -= half;
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [filteredProjects.length, filter]);

  const pauseThenResume = (delay = 1500) => {
    pausedRef.current = true;
    clearTimeout(resumeTimer.current);
    resumeTimer.current = setTimeout(() => { pausedRef.current = false; }, delay);
  };

  const onWheel = (e) => {
    const el = scrollRef.current;
    if (!el) return;
    if (Math.abs(e.deltaY) > Math.abs(e.deltaX)) {
      el.scrollLeft += e.deltaY;
      pauseThenResume();
    }
  };

  const onPointerDown = (e) => {
    const el = scrollRef.current;
    if (!el) return;
    dragRef.current = { active: true, startX: e.clientX, startScroll: el.scrollLeft, moved: false };
    pausedRef.current = true;
    el.classList.add('dragging');
  };
  const onPointerMove = (e) => {
    const el = scrollRef.current;
    if (!el || !dragRef.current.active) return;
    const dx = e.clientX - dragRef.current.startX;
    if (Math.abs(dx) > 4) dragRef.current.moved = true;
    el.scrollLeft = dragRef.current.startScroll - dx;
  };
  const endDrag = () => {
    const el = scrollRef.current;
    if (el) el.classList.remove('dragging');
    dragRef.current.active = false;
    pauseThenResume(1500);
  };

  const handleOpenDetail = async (project) => {
    setSelectedProject(project);
    setProjectDetail(null);
    setProcIdx(0);
    setDetailLoading(true);
    try {
      const data = await getProject(project.id);
      setProjectDetail(data || project);
    } catch (err) {
      console.error('Error loading project details:', err);
      setProjectDetail(project);
    } finally {
      setDetailLoading(false);
    }
  };

  const handleCloseModal = () => {
    setSelectedProject(null);
    setProjectDetail(null);
  };

  const getImgSrc = (img) =>
    img && img.startsWith('http') ? img : `${apiUrl}${img}`;

  const processImages = projectDetail?.process_images || [];
  const goProc = (dir) => setProcIdx(i => {
    const n = processImages.length;
    return (i + dir + n) % n;
  });

  const renderCard = (project, keyPrefix = '') => (
    <article
      className="project-card fp-card"
      key={`${keyPrefix}${project.id}`}
      onClick={() => { if (!dragRef.current.moved) handleOpenDetail(project); }}
    >
      <div className="project-img-wrapper">
        <img src={getImgSrc(project.img)} alt={project.title} className="project-img" loading="lazy" decoding="async" />
        <div className="project-shade" />
        <div className="project-caption">
          <span className="project-cat">{CATEGORY_LABELS[project.category] || 'รีโนเวท'}</span>
          <h3 className="project-title">{project.title}</h3>
          <span className="project-btn">ดูรายละเอียด <em>→</em></span>
        </div>
      </div>
    </article>
  );

  return (
    <section className="featured-projects" id="projects">
      <div className="container fp-head" data-aos="fade-up">
        <div>
          <p className="eyebrow">Selected Works</p>
          <h2 className="section-title">ผลงานที่ผ่านมา</h2>
        </div>
        <div className="project-filters">
          <button className={`filter-btn ${filter === 'all' ? 'active' : ''}`} onClick={() => setFilter('all')}>ทั้งหมด</button>
          <button className={`filter-btn ${filter === 'interior' ? 'active' : ''}`} onClick={() => setFilter('interior')}>ตกแต่งภายใน</button>
          <button className={`filter-btn ${filter === 'exterior' ? 'active' : ''}`} onClick={() => setFilter('exterior')}>ต่อเติมภายนอก</button>
          <button className={`filter-btn ${filter === 'renovation' ? 'active' : ''}`} onClick={() => setFilter('renovation')}>รีโนเวท</button>
        </div>
      </div>

      {loading ? (
        <p style={{ textAlign: 'center' }}>Loading projects...</p>
      ) : filteredProjects.length === 0 ? (
        <p style={{ textAlign: 'center', color: 'var(--ink-soft)' }}>ยังไม่มีผลงานในหมวดนี้</p>
      ) : (
        <div
          className="fp-scroller"
          ref={scrollRef}
          onWheel={onWheel}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={endDrag}
          onPointerLeave={endDrag}
          onMouseEnter={() => { pausedRef.current = true; }}
          onMouseLeave={() => { if (!dragRef.current.active) pausedRef.current = false; }}
        >
          {filteredProjects.map(p => renderCard(p, 'a-'))}
          {filteredProjects.map(p => renderCard(p, 'b-'))}
        </div>
      )}

      {/* Detail Modal */}
      {selectedProject && (
        <div className="project-modal-overlay" onClick={handleCloseModal}>
          <div className="project-modal" onClick={e => e.stopPropagation()}>
            <button className="project-modal-close" onClick={handleCloseModal}>✕</button>

            <div className="project-modal-hero">
              <img src={getImgSrc(selectedProject.img)} alt={selectedProject.title} />
              <span className="project-modal-category">
                {CATEGORY_LABELS[selectedProject.category] || 'รีโนเวท'}
              </span>
            </div>

            <div className="project-modal-body">
              <h2 className="project-modal-title">{selectedProject.title}</h2>

              {detailLoading ? (
                <p style={{ color: 'var(--ink-soft)', textAlign: 'center', padding: '2rem' }}>กำลังโหลด...</p>
              ) : (
                <>
                  {projectDetail?.description && (
                    <div className="project-modal-description">
                      <h4>รายละเอียดโครงการ</h4>
                      <p>{projectDetail.description}</p>
                    </div>
                  )}

                  {processImages.length > 0 && (
                    <div className="project-modal-process">
                      <h4>ภาพระหว่างดำเนินการ</h4>
                      <div className="proc-slider">
                        <div className="proc-stage">
                          <img src={getImgSrc(processImages[procIdx].img_path)} alt={processImages[procIdx].caption || 'ระหว่างดำเนินการ'} />
                          {processImages.length > 1 && (
                            <>
                              <button className="proc-nav proc-prev" onClick={() => goProc(-1)} aria-label="ก่อนหน้า">‹</button>
                              <button className="proc-nav proc-next" onClick={() => goProc(1)} aria-label="ถัดไป">›</button>
                              <span className="proc-counter">{procIdx + 1} / {processImages.length}</span>
                            </>
                          )}
                        </div>
                        {processImages[procIdx].caption && (
                          <p className="proc-caption">{processImages[procIdx].caption}</p>
                        )}
                        {processImages.length > 1 && (
                          <div className="proc-dots">
                            {processImages.map((img, i) => (
                              <button
                                key={img.id ?? i}
                                className={`proc-dot ${i === procIdx ? 'active' : ''}`}
                                onClick={() => setProcIdx(i)}
                                aria-label={`รูปที่ ${i + 1}`}
                              />
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  )}

                  {!projectDetail?.description && processImages.length === 0 && (
                    <p style={{ color: 'var(--ink-soft)', textAlign: 'center', padding: '1rem 0' }}>ยังไม่มีรายละเอียดเพิ่มเติม</p>
                  )}
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

export default FeaturedProjects;

﻿import React, { useState, useEffect } from 'react';
import { getCalculatorTypes, getBusinessInfo, submitContact, getSettings } from '../firebase/api';
import './Footer.css';

const Footer = () => {
  const [formData, setFormData] = useState({
    name: '',
    contactInfo: '',
    email: '',
    message: '',
    serviceType: ''
  });
  const [status, setStatus] = useState('');
  const [calculatorTypes, setCalculatorTypes] = useState([]);
  const [businessInfo, setBusinessInfo] = useState({
    company_name: 'BS Build',
    phone: '02-322-0000',
    line_id: '@bsbuild',
    address: 'กรุงเทพมหานคร'
  });
  // per-channel notification toggles (admin-controlled, default all on)
  const [notifEnable, setNotifEnable] = useState({ email: true, line: true, messenger: true });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [types, info, settings] = await Promise.all([
          getCalculatorTypes(),
          getBusinessInfo(),
          getSettings()
        ]);

        setCalculatorTypes(types);
        if (types.length > 0 && !formData.serviceType) {
          setFormData(prev => ({ ...prev, serviceType: types[0].type_name }));
        }

        const s = {};
        (settings || []).forEach(x => { s[x.setting_key] = x.setting_value; });
        setNotifEnable({
          email: s.notif_email !== false,
          line: s.notif_line !== false,
          messenger: s.notif_messenger !== false,
        });

        if (info) {
          setBusinessInfo({
            company_name: info.company_name || 'BS Build',
            phone: info.phone || '02-322-0000',
            line_id: info.line_id || '',
            address: info.address || 'กรุงเทพมหานคร',
            map_url: info.map_url || '',
            landmark: info.landmark || '',
            email: info.email || '',
            facebook: info.facebook || ''
          });
        }
      } catch (err) {
        console.error('Error fetching data:', err);
      }
    };
    fetchData();
  }, []);

  // Prefill the quotation form from the Calculator's "ขอใบเสนอราคา" button
  useEffect(() => {
    const handler = (e) => {
      const d = e.detail || {};
      setFormData(prev => ({
        ...prev,
        message: d.message || prev.message,
        serviceType: d.serviceType || prev.serviceType,
      }));
    };
    window.addEventListener('prefill-quote', handler);
    return () => window.removeEventListener('prefill-quote', handler);
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };


  const handleSubmit = async (e) => {
    e.preventDefault();

    // Validation (email is optional — most customers prefer Line or phone)
    if (!formData.name || !formData.contactInfo || !formData.serviceType) {
      setStatus('⚠️ โปรดกรอกข้อมูลให้ครบถ้วน');
      return;
    }

    setStatus('⏳ กำลังส่ง...');

    // Apps Script URL handles the email notification (still free, serverless).
    const APPS_SCRIPT_URL = import.meta.env.VITE_APPS_SCRIPT_URL ||
      'https://script.google.com/macros/s/AKfycbw56D651ABDA_cpQWrlqPjNl65RvR-0xkXu8YBqtF3OTRALNqOGuYDbx3AeOsvEMkQDJw/exec';

    try {
      // 1) Save to Firestore so it shows up in the admin inbox
      await submitContact(formData);
    } catch (err) {
      console.error('Firestore submit error:', err);
    }

    // 2) Fire-and-forget the Apps Script email notification
    if (APPS_SCRIPT_URL) {
      fetch(APPS_SCRIPT_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: formData.name,
          contactInfo: formData.contactInfo,
          email: formData.email,
          serviceType: formData.serviceType,
          message: formData.message,
          notify: notifEnable
        })
      }).catch(err => console.error('Apps Script notify error:', err));
    }

    setStatus('✅ ส่งคำขอประมาณการเรียบร้อย! เราจะติดต่อคุณเร็วที่สุด');
    setFormData({
      name: '',
      contactInfo: '',
      email: '',
      message: '',
      serviceType: calculatorTypes.length > 0 ? calculatorTypes[0].type_name : ''
    });
  };

  return (
    <footer className="footer" id="contact">
      <div className="container footer-container">
        <div className="footer-left">
          <h2 className="footer-title">Let's Create<br />Something Exceptional.</h2>
          <p style={{marginBottom: '2rem', color: 'var(--text-muted)'}}>ระบบขอใบเสนอราคาออนไลน์ กรอกข้อมูลเพื่อให้เราติดต่อกลับพร้อมประเมินราคาให้ฟรี!</p>
          <div className="footer-contact-info">
            {businessInfo.phone && (
            <a href={`tel:${businessInfo.phone}`} className="contact-item" title="โทรศัพท์">
              <span className="contact-icon">📞</span>
              <p>{businessInfo.phone}</p>
            </a>
            )}
            {(businessInfo.map_url || businessInfo.address) && (
            <a href={businessInfo.map_url || `https://www.google.com/maps/search/${encodeURIComponent(businessInfo.address)}`} className="contact-item" target="_blank" rel="noopener noreferrer" title="ดูแผนที่ Google Maps">
              <span className="contact-icon">📍</span>
              <p>{businessInfo.address || 'Google Maps'}</p>
            </a>
            )}
            {businessInfo.landmark && (
            <div className="contact-item" title="จุดสังเกต">
              <span className="contact-icon">⭐</span>
              <p>{businessInfo.landmark}</p>
            </div>
            )}
          </div>
        </div>
        
        <div className="footer-right">
          <form className="contact-form" onSubmit={handleSubmit} style={{background: 'rgba(255,255,255,0.02)', padding: '2rem', borderRadius: '8px', border: '1px solid rgba(255,255,255,0.1)'}}>
            <h3 style={{marginBottom: '1.5rem', color: 'var(--color-accent)'}}>ขอใบเสนอราคา (Quotation)</h3>
            <div className="form-group">
              <input type="text" name="name" placeholder="ชื่อ-นามสกุล *" value={formData.name} onChange={handleChange} required style={{background: 'rgba(255, 255, 255, 0.15)', color: '#fff', border: '1px solid rgba(255, 255, 255, 0.4)', borderRadius: '4px', padding: '0.75rem', width: '100%'}} />
              <input type="text" name="contactInfo" placeholder="Line ID / เบอร์โทร *" value={formData.contactInfo} onChange={handleChange} required style={{background: 'rgba(255, 255, 255, 0.15)', color: '#fff', border: '1px solid rgba(255, 255, 255, 0.4)', borderRadius: '4px', padding: '0.75rem', width: '100%'}} />
            </div>
            <div className="form-group" style={{marginTop: '1rem'}}>
              <select
                name="serviceType"
                value={formData.serviceType}
                onChange={handleChange}
                className="quote-select"
                style={{padding: '0.75rem', background: 'rgba(255, 255, 255, 0.15)', color: '#fff', border: '1px solid rgba(255, 255, 255, 0.4)', borderRadius: '4px', width: '100%'}}
              >
                <option value="" disabled hidden>เลือกประเภทงาน</option>
                {calculatorTypes.map(type => (
                  <option key={type.id} value={type.type_name} style={{ color: '#222', background: '#fff' }}>
                    {type.type_name}
                  </option>
                ))}
              </select>
            </div>
            <input type="email" name="email" placeholder="Email" value={formData.email} onChange={handleChange} style={{marginTop: '1rem', background: 'rgba(255, 255, 255, 0.15)', color: '#fff', border: '1px solid rgba(255, 255, 255, 0.4)', borderRadius: '4px', padding: '0.75rem', width: '100%'}} />
            <textarea name="message" placeholder="รายละเอียดงานที่ต้องการ..." rows="3" value={formData.message} onChange={handleChange} style={{marginTop: '1rem', background: 'rgba(255, 255, 255, 0.15)', color: '#fff', border: '1px solid rgba(255, 255, 255, 0.4)', borderRadius: '4px', padding: '0.75rem', width: '100%'}}></textarea>
            <button type="submit" className="btn btn-solid submit-btn" style={{width: '100%'}}>REQUEST QUOTATION</button>
            {status && <p style={{ marginTop: '1rem', color: status.includes('✅') ? '#4caf50' : '#f44336', textAlign: 'center' }}>{status}</p>}
          </form>
        </div>
      </div>
      <div className="footer-bottom">
        <div className="container">
          <div className="logo-text" style={{ fontSize: '1.5rem' }}>{businessInfo.company_name}</div>
          <p className="copyright">&copy; 2026 {businessInfo.company_name}. All rights reserved.</p>
        </div>
      </div>
    </footer>
  );
};

export default Footer;

