export default Admin;

﻿import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth } from '../firebase/config';
import '../components/Header.css';

const AdminLogin = ({ setIsAuthenticated }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      await signInWithEmailAndPassword(auth, username.trim(), password);
      setIsAuthenticated(true);
      navigate('/admin');
    } catch (err) {
      console.error('Login error:', err);
      setError('อีเมลหรือรหัสผ่านไม่ถูกต้อง');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 100%)',
      fontFamily: 'var(--font-family, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto)'
    }}>
      <div style={{
        background: 'rgba(255, 255, 255, 0.95)',
        padding: '2rem',
        borderRadius: '8px',
        boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)',
        width: '100%',
        maxWidth: '400px'
      }}>
        <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
          <h1 style={{ margin: '0 0 0.5rem', color: '#1a1a2e', fontSize: '1.8rem' }}>
            ทีมผู้รับเหมา
          </h1>
          <h2 style={{ margin: '0', color: '#666', fontSize: '1.2rem', fontWeight: 'normal' }}>
            Admin Dashboard
          </h2>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '1rem' }}>
            <label style={{
              display: 'block',
              marginBottom: '0.5rem',
              color: '#333',
              fontWeight: '500'
            }}>
              Email
            </label>
            <input
              type="email"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="admin@example.com"
              required
              style={{
                width: '100%',
                padding: '0.75rem',
                border: '1px solid #ddd',
                borderRadius: '4px',
                fontSize: '1rem',
                boxSizing: 'border-box'
              }}
            />
          </div>

          <div style={{ marginBottom: '1.5rem' }}>
            <label style={{
              display: 'block',
              marginBottom: '0.5rem',
              color: '#333',
              fontWeight: '500'
            }}>
              Password
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter password"
              required
              style={{
                width: '100%',
                padding: '0.75rem',
                border: '1px solid #ddd',
                borderRadius: '4px',
                fontSize: '1rem',
                boxSizing: 'border-box'
              }}
            />
          </div>

          {error && (
            <div style={{
              color: '#d32f2f',
              marginBottom: '1rem',
              padding: '0.75rem',
              background: '#ffebee',
              borderRadius: '4px',
              fontSize: '0.9rem'
            }}>
              {error}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            style={{
              width: '100%',
              padding: '0.75rem',
              background: loading ? '#ccc' : '#1a1a2e',
              color: '#fff',
              border: 'none',
              borderRadius: '4px',
              fontSize: '1rem',
              fontWeight: '600',
              cursor: loading ? 'not-allowed' : 'pointer',
              transition: 'background 0.3s'
            }}
            onMouseEnter={(e) => !loading && (e.target.style.background = '#0d0d1a')}
            onMouseLeave={(e) => !loading && (e.target.style.background = '#1a1a2e')}
          >
            {loading ? 'Logging in...' : 'Login'}
          </button>
        </form>

        <p style={{
          textAlign: 'center',
          color: '#999',
          marginTop: '1.5rem',
          fontSize: '0.9rem'
        }}>
          Professional Construction Management System
        </p>
      </div>
    </div>
  );
};

export default AdminLogin;

import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { getArticleBySlug } from '../firebase/api';
import Header from '../components/Header';
import Footer from '../components/Footer';
import LineButton from '../components/LineButton';
import useSeo from '../lib/useSeo';
import './Article.css';

const fmtDate = (d) => {
  try {
    return new Date(d).toLocaleDateString('th-TH', { year: 'numeric', month: 'long', day: 'numeric' });
  } catch { return ''; }
};

const Article = () => {
  const { slug } = useParams();
  const [article, setArticle] = useState(undefined); // undefined = loading, null = not found

  useEffect(() => {
    let alive = true;
    getArticleBySlug(slug)
      .then(a => { if (alive) setArticle(a); })
      .catch(() => { if (alive) setArticle(null); });
    return () => { alive = false; };
  }, [slug]);

  useSeo(article ? {
    title: `${article.title} | BSBuildTh`,
    description: article.excerpt,
    image: article.cover && article.cover.startsWith('http') ? article.cover : undefined,
    canonical: `https://bsbuildth.github.io/blog/${article.slug}`,
    jsonLd: {
      '@context': 'https://schema.org',
      '@type': 'Article',
      headline: article.title,
      description: article.excerpt,
      datePublished: article.created_at,
      author: { '@type': 'Organization', name: 'BSBuildTh' },
      publisher: { '@type': 'Organization', name: 'BSBuildTh' },
    },
  } : {});

  const paragraphs = (article?.content || '').split(/\n{2,}/).map(p => p.trim()).filter(Boolean);

  return (
    <>
      <Header />
      <main className="article-page">
        {article === undefined ? (
          <p className="article-empty">กำลังโหลด...</p>
        ) : article === null ? (
          <div className="article-empty">
            <p>ไม่พบบทความนี้</p>
            <Link to="/blog" className="article-back">← กลับไปหน้าบทความ</Link>
          </div>
        ) : (
          <article className="article-wrap">
            <Link to="/blog" className="article-back">← บทความทั้งหมด</Link>

            {article.category && <span className="article-cat">{article.category}</span>}
            <h1 className="article-title">{article.title}</h1>
            <p className="article-date">{fmtDate(article.created_at)}</p>

            {article.cover && (
              <div className="article-cover">
                <img src={article.cover} alt={article.title} decoding="async" />
              </div>
            )}

            <div className="article-body">
              {paragraphs.map((p, i) => <p key={i}>{p}</p>)}
            </div>

            <div className="article-cta">
              <h3>สนใจต่อเติม–รีโนเวทบ้าน?</h3>
              <p>ปรึกษาฟรี ประเมินราคาเบื้องต้นโดยทีมช่างประสบการณ์กว่า 30 ปี</p>
              <a href="/#contact" className="btn btn-solid">ขอใบเสนอราคา →</a>
            </div>
          </article>
        )}
      </main>
      <Footer />
      <LineButton />
    </>
  );
};

export default Article;

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { getArticles } from '../firebase/api';
import Header from '../components/Header';
import Footer from '../components/Footer';
import LineButton from '../components/LineButton';
import useSeo from '../lib/useSeo';
import './Blog.css';

const fmtDate = (d) => {
  try {
    return new Date(d).toLocaleDateString('th-TH', { year: 'numeric', month: 'long', day: 'numeric' });
  } catch { return ''; }
};

const Blog = () => {
  const [articles, setArticles] = useState([]);
  const [loading, setLoading] = useState(true);

  useSeo({
    title: 'บทความ & ความรู้งานต่อเติม–รีโนเวทบ้าน | BSBuildTh',
    description: 'รวมบทความ ไอเดีย และความรู้เรื่องต่อเติมบ้าน รีโนเวทบ้าน และการเลือกผู้รับเหมา จากทีมช่างประสบการณ์กว่า 30 ปี',
    canonical: 'https://bsbuildth.github.io/blog',
  });

  useEffect(() => {
    getArticles()
      .then(data => { setArticles(data); setLoading(false); })
      .catch(err => { console.error('Failed to load articles:', err); setLoading(false); });
  }, []);

  return (
    <>
      <Header />
      <main className="blog-page">
        <div className="blog-hero">
          <span className="blog-eyebrow">ARTICLES & KNOWLEDGE</span>
          <h1 className="blog-title">บทความ & ความรู้</h1>
          <p className="blog-sub">ไอเดียและคำแนะนำเรื่องต่อเติม–รีโนเวทบ้าน จากทีมช่างประสบการณ์กว่า 30 ปี</p>
        </div>

        <div className="blog-container">
          {loading ? (
            <p className="blog-empty">กำลังโหลดบทความ...</p>
          ) : articles.length === 0 ? (
            <p className="blog-empty">ยังไม่มีบทความ</p>
          ) : (
            <div className="blog-grid">
              {articles.map(a => (
                <Link to={`/blog/${a.slug}`} className="blog-card" key={a.id}>
                  <div className="blog-card-img">
                    {a.cover && <img src={a.cover} alt={a.title} loading="lazy" decoding="async" />}
                  </div>
                  <div className="blog-card-body">
                    {a.category && <span className="blog-card-cat">{a.category}</span>}
                    <h2 className="blog-card-title">{a.title}</h2>
                    <p className="blog-card-excerpt">{a.excerpt}</p>
                    <div className="blog-card-foot">
                      <span className="blog-card-date">{fmtDate(a.created_at)}</span>
                      <span className="blog-card-more">อ่านต่อ →</span>
                    </div>
                  </div>
                </Link>
              ))}
            </div>
          )}
        </div>
      </main>
      <Footer />
      <LineButton />
    </>
  );
};

export default Blog;
